// Generated by scripts/sync-core.mjs from mobile/tests/request.test.ts; edit it there and run npm run sync-core.
// Payment codes and the QR codes that carry them: what Receive shows must be
// what Send reads back, through an independent QR decoder.
import { describe, expect, it } from 'vitest';
import jsQR from 'jsqr';
import { encodeRequest, parseRequest } from '../src/core/chain/request';
import { qrShape } from '../src/core/qrShape';

const account = '3469bc010fc4e7f8dc4a80882f2a9934458c96984d9df94a2e0c3c3092615bc3';
const coin = '2fed0789aa0b1c2d3e4f5a6b7c8d9e0f112233445566778899aabbccdd12210b';

describe('payment codes', () => {
  it('encodes an account, with or without a coin', () => {
    expect(encodeRequest({ account })).toBe(`ting:${account}`);
    expect(encodeRequest({ account: account.toUpperCase(), coin })).toBe(`ting:${account}?coin=${coin}`);
  });

  it('rejects what is not 32 bytes', () => {
    expect(() => encodeRequest({ account: account.slice(2) })).toThrow();
    expect(() => encodeRequest({ account, coin: 'zz' })).toThrow();
  });

  it('reads codes, bare accounts and tolerated variants', () => {
    expect(parseRequest(`ting:${account}`)).toEqual({ account });
    expect(parseRequest(`  Ting:${account.toUpperCase()}?coin=${coin.toUpperCase()}\n`)).toEqual({ account, coin });
    expect(parseRequest(`ting://${account}/?coin=${coin}`)).toEqual({ account, coin });
    expect(parseRequest(`ting:${account}?label=Anna&coin=${coin}&x`)).toEqual({ account, coin });
    expect(parseRequest(account)).toEqual({ account });
  });

  it('refuses everything else', () => {
    for (const text of [
      '',
      'ting:',
      `ting:${account}00`,
      `ting:${account.slice(1)}`,
      `ting:${account}?coin=`,
      `ting:${account}?coin=${coin.slice(2)}`,
      `bitcoin:${account}`,
      `https://example.com/${account}`,
      'hello',
    ]) {
      expect(parseRequest(text), text).toBeNull();
    }
  });
});

/** Draws a shape's path, as the apps' SVG does, into an RGBA image with a quiet zone. */
function rasterize(text: string, scale = 4, quiet = 4) {
  const { size, path } = qrShape(text);
  const dark = Array.from({ length: size }, () => new Array<boolean>(size).fill(false));
  const runs = [...path.matchAll(/M(\d+) (\d+)h(\d+)v1h-(\d+)z/g)];
  expect(runs.map((m) => m[0]).join('')).toBe(path);
  for (const [, x, y, w, back] of runs) {
    expect(back).toBe(w);
    for (let i = 0; i < Number(w); i++) {
      expect(dark[Number(y)][Number(x) + i]).toBe(false);
      dark[Number(y)][Number(x) + i] = true;
    }
  }
  const width = (size + 2 * quiet) * scale;
  const pixels = new Uint8ClampedArray(width * width * 4).fill(255);
  for (let py = 0; py < width; py++) {
    for (let px = 0; px < width; px++) {
      const mx = Math.floor(px / scale) - quiet;
      const my = Math.floor(py / scale) - quiet;
      if (mx >= 0 && my >= 0 && mx < size && my < size && dark[my][mx]) {
        const at = (py * width + px) * 4;
        pixels[at] = pixels[at + 1] = pixels[at + 2] = 0;
      }
    }
  }
  return { size, pixels, width };
}

describe('QR codes', () => {
  it('decode to the payment code they were drawn from', () => {
    for (const text of [encodeRequest({ account }), encodeRequest({ account, coin }), account]) {
      const { pixels, width } = rasterize(text);
      expect(jsQR(pixels, width, width)?.data).toBe(text);
    }
  });

  it('stay small enough to scan from a screen', () => {
    expect(qrShape(encodeRequest({ account })).size).toBe(37);
    expect(qrShape(encodeRequest({ account, coin })).size).toBe(49);
  });
});
